      var updates = [];
      entries.forEach(function (e) {
        var c = String((e && (e.comment || e.name || e.title)) || '');
        if (on[c]) updates.push({ uid: e.uid, enabled: true });
        else if (off[c]) updates.push({ uid: e.uid, enabled: false });
      });
      if (updates.length) {
        await setLorebookEntries(book, updates);
        console.log('[第一幕] 世界书『' + book + '』翻动 ' + updates.length + ' 条');
