    /* 开：本条绑定 + 本线DLC主条目；关：其他所有开场白绑定 + 其他线DLC主条目 */
    var enable = item.open.slice();
    if (group.lineEntry) enable.push(group.lineEntry);
    var disable = [];
    GS_CONFIG.groups.forEach(function (g) {
      if (g !== group && g.lineEntry) disable.push(g.lineEntry);
      g.items.forEach(function (it) {
        if (it !== item) disable = disable.concat(it.open);
      });
    });
    await gsFlipEntries(enable, disable);

    gsOverlay('正在加载开场…');
    await gsJumpToPage(item.page);
