function gsRender(cur) {
  var root = document.querySelector('.gs-wrap');
  if (!root) return;
  var listEl = root.querySelector('.gs-list');
  if (!listEl) return;

  var html = '';
  GS_CONFIG.groups.forEach(function (g) {
    html += '<div class="gs-group">';
    html += '<div class="gs-group-head">';
    html += '<span class="gs-group-icon"><i class="' + gsEsc(g.icon) + '"></i></span>';
    html += '<span class="gs-group-name">' + gsEsc(g.label) + '</span>';
    if (g.sub) html += '<span class="gs-group-sub">' + gsEsc(g.sub) + '</span>';
    html += '<span class="gs-group-line"></span>';
    html += '</div>';
    g.items.forEach(function (it) {
      html += '<div class="gs-item' + (it.page === cur ? ' gs-current' : '') + '" data-page="' + it.page + '">';
      html += '<div class="gs-item-body">';
      html += '<span class="gs-item-title">' + gsEsc(it.title) + '</span>';
      if (it.ifName) html += '<span class="gs-if-badge">' + gsEsc(it.ifName) + '</span>';
      html += '</div>';
      html += '<span class="gs-item-page">#' + it.page + '</span>';
      html += '</div>';
    });
    html += '</div>';
  });
  listEl.innerHTML = html;

  listEl.querySelectorAll('.gs-item').forEach(function (el) {
    el.addEventListener('click', function () {
      var page = Number(el.getAttribute('data-page'));
      for (var gi = 0; gi < GS_CONFIG.groups.length; gi++) {
        var g = GS_CONFIG.groups[gi];
        for (var ii = 0; ii < g.items.length; ii++) {
          if (g.items[ii].page === page) { gsPick(g, g.items[ii]); return; }
        }
      }
    });
  });
}

setTimeout(async function () {
  gsRender(await gsCurrentPage());
}, 100);
</script>

