<body>

<!-- ===== 静态外壳 ===== -->
<div class="nm-status">
  <div class="nm-card">
    <div class="nm-title-bar">
      <span class="nm-title-line"></span>
      <span class="nm-title-icon"><i class="fa-solid fa-moon"></i></span>
      <span class="nm-title-text">此刻</span>
      <span class="nm-title-line"></span>
    </div>
    <div class="nm-env"></div>
    <div class="nm-slots"></div>
    <div class="nm-footer">
      <div class="nm-footer-dots">
        <span class="nm-footer-dot"></span>
        <span class="nm-footer-dot nm-dot-accent"></span>
        <span class="nm-footer-dot"></span>
      </div>
    </div>
  </div>
</div>

<script>
/* =====================================================================
 * 正则用法（SillyTavern 正则替换）：
 *   匹配：<status>([\s\S]+?)<\/status>
 *   替换为：本文件中 <div class="nm-status">…</div> 与脚本部分。
 *   下方 String.raw`$1` 即为动态注入的捕获内容，无需改动。
 * ===================================================================== */

var NMICONS = {
  '着装': 'fa-solid fa-tag',
  '衣着': 'fa-solid fa-tag',
  '姿态': 'fa-solid fa-user',
  '位置': 'fa-solid fa-location-dot',
  '状态': 'fa-solid fa-circle-info'
};

/* 天气 → 图标 */
function nmWeatherIcon(w) {
  if (/雷/.test(w)) return 'fa-solid fa-cloud-bolt';
  if (/雪/.test(w)) return 'fa-solid fa-snowflake';
  if (/雨/.test(w)) return 'fa-solid fa-cloud-rain';
  if (/阴|云/.test(w)) return 'fa-solid fa-cloud';
  if (/晴/.test(w)) return 'fa-solid fa-sun';
  return 'fa-solid fa-cloud-sun';
}

/* HTML 转义，防止模型输出里的特殊字符破坏结构 */
function nmEsc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function nmParseStatus(raw) {
  var result = { env: [], characters: [], relations: {} };

  /* --- 环境：形如 日期 星期|时间|地点|天气 --- */
  var envMatch = raw.match(/<环境>([\s\S]+?)<\/环境>/);
  if (envMatch) {
    result.env = envMatch[1].split('|').map(function(s) { return s.trim(); }).filter(Boolean);
  }

  /* --- 关系总览：每行「名字：关系」 --- */
  var relMatch = raw.match(/<关系总览>([\s\S]+?)<\/关系总览>/);
  if (relMatch) {
    relMatch[1].trim().split(/\r?\n/).forEach(function(line) {
      var m = line.match(/(.+?)[：:](.+)/);
      if (m) result.relations[m[1].trim()] = m[2].trim();
    });
  }

  /* --- 角色块：除环境/关系总览外的所有角色标签 ---
     只跳过真 HTML 标签（ST 渲染残留，按裸名名单）；英文名角色（<Lucas>）正常解析 */
  var cleaned = raw
    .replace(/<环境>[\s\S]+?<\/环境>/g, '')
    .replace(/<关系总览>[\s\S]+?<\/关系总览>/g, '');

  var HTML_TAG_DENY = ('div span font br b i u s em strong sub sup code pre blockquote a img hr ul ol li p ' +
    'h1 h2 h3 h4 h5 h6 details summary table tr td th thead tbody small mark svg path g rect circle defs use symbol').split(' ');
  var openTagRegex = /<([^/<>\s][^<>]*)>/g;
  var tags = [];
  var m;
  while ((m = openTagRegex.exec(cleaned)) !== null) {
    var tagName = m[1].trim();
    if (tagName === 'status') continue; // 外层壳若意外混入（正则只注入内瓤，这里纯保险）
    var bare = tagName.replace(/\/+$/, '').split(/\s+/)[0].toLowerCase(); // 去尾斜杠/属性取裸名：<font color=…> → font
    if (HTML_TAG_DENY.indexOf(bare) !== -1) continue;
    if (tagName.length > 20) continue;
    tags.push({ name: tagName, contentStart: m.index + m[0].length });
  }
  tags.forEach(function(tag) {
    var closeStr = '</' + tag.name + '>';
    var endIdx = cleaned.indexOf(closeStr, tag.contentStart);
    if (endIdx === -1) return;
    var content = cleaned.substring(tag.contentStart, endIdx).trim();
    var fields = [];
    content.split(/\r?\n/).forEach(function(line) {
      var fm = line.match(/^(.+?)[：:]\s*(.*)/);
      if (fm) fields.push({ key: fm[1].trim(), value: fm[2].trim() });
    });
    if (fields.length > 0) {
      result.characters.push({ name: tag.name, fields: fields });
    }
  });
  return result;
}

function nmRenderEnv(env) {
  if (!env.length) return '';
  var icons = ['fa-solid fa-calendar-day', 'fa-solid fa-clock'];
  var html = '';
  env.forEach(function(seg, i) {
    var icon;
    if (i === 0) icon = icons[0];
    else if (i === 1) icon = icons[1];
    else if (i === env.length - 1 && /晴|阴|雨|雪|雷|云|雾/.test(seg)) icon = nmWeatherIcon(seg);
    else icon = 'fa-solid fa-location-dot';
    if (i > 0) html += '<span class="nm-env-sep"></span>';
    html += '<span class="nm-env-item"><i class="' + icon + '"></i>' + nmEsc(seg) + '</span>';
  });
  return html;
}

function nmRenderSlot(char, index, relations) {
  var initial = nmEsc(char.name.charAt(0));
  /* 初始状态：所有栏目默认收起 */
  /* 关系跟角色走：该角色有关系才显示，没有就不渲染（含蒋默保底条目） */
  var rel = relations[char.name];

  var html = '<details class="nm-slot">';
  html += '<summary class="nm-slot-header">';
  html += '<div class="nm-avatar">' + initial + '</div>';
  html += '<div class="nm-slot-id">';
  html += '<span class="nm-slot-name">' + nmEsc(char.name) + '</span>';
  if (rel) {
    html += '<span class="nm-rel-badge">' + nmEsc(rel) + '</span>';
  }
  html += '</div>';
  html += '<span class="nm-arrow"><i class="fa-solid fa-chevron-down"></i></span>';
  html += '</summary>';
  html += '<div class="nm-slot-body"><div class="nm-divider"></div>';

  char.fields.forEach(function(f) {
    if (f.key === '心声') return;
    var iconClass = NMICONS[f.key] || 'fa-solid fa-circle';
    html += '<div class="nm-field">';
    html += '<div class="nm-field-icon"><i class="' + iconClass + '"></i></div>';
    html += '<div class="nm-field-body">';
    html += '<div class="nm-field-label">' + nmEsc(f.key) + '</div>';
    html += '<div class="nm-field-value">' + nmEsc(f.value) + '</div>';
    html += '</div></div>';
  });

  var thought = null;
  for (var i = 0; i < char.fields.length; i++) {
    if (char.fields[i].key === '心声') { thought = char.fields[i]; break; }
  }
  if (thought) {
    html += '<div class="nm-thought">';
    html += '<div class="nm-thought-label"><i class="fa-solid fa-heart"></i> 心声</div>';
    html += '<div class="nm-thought-text">' + nmEsc(thought.value) + '</div>';
    html += '</div>';
  }

  html += '</div></details>';
  return html;
}

function nmInit() {
  var container = document.querySelector('.nm-status');
  if (!container) return;

  /* ===== $1 由酒馆正则捕获注入，直接解析 ===== */
  var rawData = String.raw`$1`;

  var data = nmParseStatus(rawData);

  var envEl = container.querySelector('.nm-env');
  if (envEl) envEl.innerHTML = nmRenderEnv(data.env);

  var total = data.characters.length;
  console.log('[nm-status] 解析到', total, '个角色:', data.characters.map(function(c) { return c.name; }));
  if (total === 0) return;

  var slotsEl = container.querySelector('.nm-slots');
  if (!slotsEl) return;

  var html = '';
  data.characters.forEach(function(char, i) {
    html += nmRenderSlot(char, i, data.relations);
  });
  slotsEl.innerHTML = html;

  /* 展开态视觉：JS 直接写内联样式（不依赖任何CSS选择器，防止主题覆盖）——
     箭头朝上=左上阴影+右下高光的凹陷按压感；头像恒定凸起不跟随状态 */
  var ARROW_RAISED = '2px 2px 5px #c8ccd3, -2px -2px 5px #feffff';
  var ARROW_INSET  = 'inset -2px -2px 4px #c8ccd3, inset 2px 2px 4px #ffffff';
  slotsEl.querySelectorAll('details.nm-slot').forEach(function (d) {
    var arrow = d.querySelector('.nm-arrow');
    if (!arrow) return;
    var sync = function () {
      d.classList.toggle('nm-open', d.open);
      arrow.style.transform = d.open ? 'rotate(180deg)' : '';
      arrow.style.boxShadow = d.open ? ARROW_INSET : ARROW_RAISED;
    };
    d.addEventListener('toggle', sync);
    sync();
  });
}

setTimeout(nmInit, 100);
</script>

</body>
</html>
